import React, { useState, useMemo } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import useLocalStorage from './hooks/useLocalStorage';

// Pages
import HomePage from './pages/HomePage';
import TestPage from './pages/TestPage';
import LeaderboardPage from './pages/LeaderboardPage';
import AdminLoginPage from './pages/AdminLoginPage';
import AdminDashboardPage from './pages/AdminDashboardPage';
import ManageQuestionsPage from './pages/ManageQuestionsPage';
import AdminSettingsPage from './pages/AdminSettingsPage';

// Auth Context
export const AuthContext = React.createContext<{
  isAdmin: boolean;
  login: (password: string) => boolean;
  logout: () => void;
} | null>(null);

const ADMIN_PASSWORD = 'admin123';

const AdminRoute: React.FC<{ children: React.ReactElement }> = ({ children }) => {
  const auth = React.useContext(AuthContext);
  if (!auth?.isAdmin) {
    return <Navigate to="/admin" replace />;
  }
  return children;
};

function App() {
  const [isAdmin, setIsAdmin] = useLocalStorage('isAdmin', false);

  const authContextValue = useMemo(() => ({
    isAdmin,
    login: (password: string) => {
      if (password === ADMIN_PASSWORD) {
        setIsAdmin(true);
        return true;
      }
      return false;
    },
    logout: () => {
      setIsAdmin(false);
    },
  }), [isAdmin, setIsAdmin]);

  return (
    <AuthContext.Provider value={authContextValue}>
      <HashRouter>
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route path="/test/:testType" element={<TestPage />} />
          <Route path="/leaderboard" element={<LeaderboardPage />} />
          <Route path="/admin" element={<AdminLoginPage />} />
          <Route 
            path="/admin/dashboard" 
            element={<AdminRoute><AdminDashboardPage /></AdminRoute>} 
          />
          <Route 
            path="/admin/questions" 
            element={<AdminRoute><ManageQuestionsPage /></AdminRoute>} 
          />
          <Route 
            path="/admin/settings" 
            element={<AdminRoute><AdminSettingsPage /></AdminRoute>} 
          />
          <Route path="*" element={<Navigate to="/" />} />
        </Routes>
      </HashRouter>
    </AuthContext.Provider>
  );
}

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import useLocalStorage from '../hooks/useLocalStorage';
import { Question, TestType, UserScore } from '../types';

const shuffleArray = <T,>(array: T[]): T[] => {
  return [...array].sort(() => Math.random() - 0.5);
};

const TestPage: React.FC = () => {
  const { testType } = useParams<{ testType: TestType }>();
  const navigate = useNavigate();
  const [questions] = useLocalStorage<Question[]>('questions', []);
  const [, setScores] = useLocalStorage<UserScore[]>('scores', []);
  const [googleScriptUrl] = useLocalStorage<string>('googleScriptUrl', '');

  const [testQuestions, setTestQuestions] = useState<Question[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [userAnswers, setUserAnswers] = useState<(number | null)[]>([]);
  const [isFinished, setIsFinished] = useState(false);
  const [score, setScore] = useState(0);
  const [userName, setUserName] = useState('');
  const [showModal, setShowModal] = useState(false);

  useEffect(() => {
    if (questions.length > 0) {
      const shuffled = shuffleArray(questions);
      setTestQuestions(shuffled.slice(0, 10));
      setUserAnswers(new Array(10).fill(null));
    }
  }, [questions]);

  const handleAnswerSelect = (optionIndex: number) => {
    if (isFinished) return;
    const newAnswers = [...userAnswers];
    newAnswers[currentQuestionIndex] = optionIndex;
    setUserAnswers(newAnswers);
  };

  const handleNext = () => {
    if (currentQuestionIndex < testQuestions.length - 1) {
      setCurrentQuestionIndex(prev => prev + 1);
    } else {
      finishTest();
    }
  };

  const finishTest = () => {
    let calculatedScore = 0;
    testQuestions.forEach((q, index) => {
      if (userAnswers[index] === q.correctAnswerIndex) {
        calculatedScore += 10;
      }
    });
    setScore(calculatedScore);
    setIsFinished(true);
    setShowModal(true);
  };

  const saveScore = async () => {
    if (!userName.trim()) {
      alert("Please enter your name.");
      return;
    }
    const newScore: UserScore = {
      id: new Date().toISOString(),
      name: userName,
      score: score,
      testType: testType!,
      timestamp: Date.now(),
    };

    // Save locally
    setScores(prevScores => [...prevScores, newScore]);

    // Save to Google Sheets if configured
    if (googleScriptUrl) {
      try {
        await fetch(googleScriptUrl, {
          method: 'POST',
          mode: 'no-cors', // Essential for GAS Web Apps
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(newScore),
        });
        console.log("Score sent to Google Sheets");
      } catch (error) {
        console.error("Failed to send to Google Sheets", error);
      }
    }

    setShowModal(false);
    navigate('/leaderboard');
  };

  const currentQuestion = testQuestions[currentQuestionIndex];
  const progress = useMemo(() => ((currentQuestionIndex + 1) / testQuestions.length) * 100, [currentQuestionIndex, testQuestions.length]);

  if (questions.length < 10) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-100 p-4 text-center">
        <h1 className="text-3xl font-bold text-red-600 mb-4">Not Enough Questions</h1>
        <p className="text-lg text-gray-700">An admin needs to add at least 10 questions to start a test.</p>
        <button onClick={() => navigate('/')} className="mt-6 bg-blue-600 text-white font-bold py-2 px-6 rounded-lg hover:bg-blue-700 transition-colors">
          Go to Homepage
        </button>
      </div>
    );
  }

  if (testQuestions.length === 0) {
     return <div className="min-h-screen flex items-center justify-center bg-gray-100">Loading...</div>;
  }

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col items-center justify-center p-4">
      <div className="w-full max-w-3xl bg-white rounded-2xl shadow-xl p-8">
        <h1 className="text-3xl font-bold text-center text-gray-800 mb-2 capitalize">
          {testType?.replace('-', ' ')}
        </h1>
        <p className="text-center text-gray-500 mb-6">Question {currentQuestionIndex + 1} of {testQuestions.length}</p>

        <div className="w-full bg-gray-200 rounded-full h-2.5 mb-8">
          <div className="bg-blue-600 h-2.5 rounded-full transition-all duration-500" style={{ width: `${progress}%` }}></div>
        </div>

        <div>
          <h2 className="text-2xl font-semibold text-gray-800 mb-6">{currentQuestion.questionText}</h2>
          <div className="space-y-4">
            {currentQuestion.options.map((option, index) => (
              <button
                key={index}
                onClick={() => handleAnswerSelect(index)}
                className={`w-full text-left p-4 rounded-lg border-2 transition-all duration-200 ${
                  userAnswers[currentQuestionIndex] === index
                    ? 'bg-blue-500 border-blue-500 text-white font-semibold shadow-lg'
                    : 'bg-white border-gray-300 hover:border-blue-400 hover:bg-blue-50'
                }`}
              >
                <span className="font-bold mr-3">{String.fromCharCode(65 + index)}.</span> {option}
              </button>
            ))}
          </div>
        </div>

        <div className="mt-8 flex justify-end">
          <button
            onClick={handleNext}
            className="bg-blue-600 text-white font-bold py-3 px-8 rounded-lg hover:bg-blue-700 transition-colors disabled:bg-gray-400"
            disabled={userAnswers[currentQuestionIndex] === null}
          >
            {currentQuestionIndex < testQuestions.length - 1 ? 'Next' : 'Finish'}
          </button>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-2xl p-8 m-4 max-w-md w-full text-center">
            <h2 className="text-3xl font-bold text-gray-800 mb-4">Test Complete!</h2>
            <p className="text-5xl font-bold text-blue-600 mb-6">{score}<span className="text-2xl text-gray-500">/100</span></p>
            <div className="mb-6">
              <input
                type="text"
                value={userName}
                onChange={(e) => setUserName(e.target.value)}
                placeholder="Enter your name to save score"
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:outline-none"
              />
            </div>
            <button
              onClick={saveScore}
              className="w-full bg-blue-600 text-white font-bold py-3 px-6 rounded-lg hover:bg-blue-700 transition-colors"
            >
              Save Score & View Leaderboard
            </button>
             <button onClick={() => navigate('/')} className="mt-4 text-gray-500 hover:text-gray-700">
                Back to Home
              </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default TestPage;

